{
  "mcpServers": {
    "playwright": {
      "command": "npx",
      "args": ["-y", "@playwright/mcp", "--headless"]
    },
    "github": {
      "type": "http",
      "url": "https://api.githubcopilot.com/mcp",
      "headers": {
        "Authorization": "Bearer $GITHUB_TOKEN"
      }
    },
    "postgres": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-postgres"],
      "env": {
        "POSTGRES_CONNECTION_STRING": "$DATABASE_URL"
      }
    }
  }
}

{
  "mcpServers": {
    "internal-api": {
      "type": "http",
      "url": "https://api.internal.company.com/mcp",
      "headers": {
        "Authorization": "Bearer ${API_TOKEN}",
        "X-Team-ID": "${TEAM_ID}",
        "X-Environment": "development"
      }
    }
  }
}

# Poorly designed MCP response: says nothing actionable
{"isError": True, "content": [{"type": "text", "text": "Operation failed"}]}

# Well-designed MCP response: structured metadata + readable explanation
{
    "isError": True,
    "content": [{
        "type": "text",
        "text": json.dumps({
            "errorCategory": "business",
            "isRetryable": False,
            "message": "The requested amount ($650) exceeds the auto-approval limit ($500) without supervisor review.",
            "suggestedAction": "escalate_to_human",
        })
    }]
}

{
  "permissions": {
    "deny": ["mcp__puppeteer"]
  }
}
// Pattern: mcp__<server-name>

{
  "permissions": {
    "allow": [
      "mcp__github__list_issues",
      "mcp__github__get_issue",
      "mcp__github__list_prs"
    ],
    "deny": ["mcp__github"]
  }
}
// Pattern: mcp__<server>__<tool-name>

{
  "permissions": {
    "deny": [
      "mcp__github__delete_repository",
      "mcp__github__delete_branch"
    ]
  }
}
// The rest of the server's tools remain available

{
  "mcpServers": {
    "inventory": {
      "command": "npx",
      "args": ["-y", "@mcp/inventory"],
      "timeout": 30000
    }
  }
}
